def transform(grid):
    # Objects are mirrored across a horizontal axis and move to the bottom; preserve shapes/colors.
    h, w = len(grid), len(grid[0])
    out = [[0]*w for _ in range(h)]
    colors = {v for row in grid for v in row if v}
    # each distinct color component is flipped vertically, with each color block shifted to occupy lower rows
    for c in colors:
        cells=[(r,k) for r in range(h) for k in range(w) if grid[r][k]==c]
        # group 4-neighbor components separately
        unseen=set(cells)
        while unseen:
            stack=[unseen.pop()]; comp=[]
            while stack:
                r,k=stack.pop(); comp.append((r,k))
                for p in ((r-1,k),(r+1,k),(r,k-1),(r,k+1)):
                    if p in unseen: unseen.remove(p); stack.append(p)
            minr=min(r for r,k in comp); maxr=max(r for r,k in comp)
            # flip component vertically in place around its own bounding box
            for r,k in comp:
                out[minr+maxr-r][k]=c
    return out
