def transform(grid):
    h,w=len(grid),len(grid[0]); out=[[0]*w for _ in range(h)]
    # Flip each connected nonzero object vertically, then let objects fall to the lowest available position.
    comps=[]; seen=set()
    for r in range(h):
      for c in range(w):
       if not grid[r][c] or (r,c) in seen: continue
       color=grid[r][c]; q=[(r,c)]; seen.add((r,c)); comp=[]
       while q:
        a,b=q.pop(); comp.append((a,b))
        for x,y in ((a-1,b),(a+1,b),(a,b-1),(a,b+1)):
         if 0<=x<h and 0<=y<w and grid[x][y]==color and (x,y) not in seen:
          seen.add((x,y));q.append((x,y))
       lo=min(a for a,b in comp); hi=max(a for a,b in comp)
       flipped={(lo+hi-a,b) for a,b in comp}
       comps.append((flipped,color))
    # find downward shift per object without overlap, bottom-first order
    comps.sort(key=lambda z:max(a for a,b in z[0]), reverse=True)
    for shape,color in comps:
      shift=0
      while True:
       nxt={(a+shift+1,b) for a,b in shape}
       if any(a>=h for a,b in nxt) or any(out[a][b] not in (0,color) for a,b in nxt): break
       shift+=1
      for a,b in ((a+shift,b) for a,b in shape): out[a][b]=color
    return out
